package com.nequard.security;
import com.nequard.auth.OrganizationAccessService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/security") public class SecurityController{private final SecurityEventRepository repo;private final OrganizationAccessService access;public SecurityController(SecurityEventRepository r,OrganizationAccessService a){repo=r;access=a;}@GetMapping("/events")public List<SecurityEvent> events(Authentication a){if(access.isSuperAdmin(a))return repo.findTop100ByOrderByOccurredAtDesc();UUID org=access.currentOrganization(a);return repo.findTop100ByOrganizationIdOrderByOccurredAtDesc(org);}@PostMapping("/events")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','SECURITY_ANALYST')")public SecurityEvent record(Authentication a,@RequestBody SecurityEvent e){e.setOrganizationId(access.requireOrganization(a,e.getOrganizationId()));return repo.save(e);}}